const items = $input.all();

return items.map((item) => {
  const preguntaOriginal = (item.json.pregunta_usuario || "").toString().trim();

  const preguntaSinTildes = preguntaOriginal
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

  const preguntaNormalizada = preguntaSinTildes
    .toLowerCase()
    .replace(/[¿?¡!.,;:()[\]{}"'`´]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  return {
    json: {
      ...item.json,
      pregunta_original: preguntaOriginal,
      pregunta_normalizada: preguntaNormalizada,
      pregunta_valida: preguntaNormalizada.length > 0,
      longitud_pregunta: preguntaOriginal.length
    }
  };
});

const items = $input.all();

function normalizarTexto(texto) {
  return String(texto || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function contieneAlguno(texto, patrones) {
  return patrones.some((patron) => texto.includes(patron));
}

function coincideAlguno(texto, regexList) {
  return regexList.some((regex) => regex.test(texto));
}

return items.map((item) => {
  const data = item.json;

  const preguntaOriginal =
    data.pregunta_usuario ||
    data.pregunta_original ||
    "";

  const preguntaNormalizada =
    data.pregunta_normalizada ||
    normalizarTexto(preguntaOriginal);

  const pregunta = normalizarTexto(preguntaNormalizada);

  const score = {
    fuera_alcance: 0,
    reserva_simulada: 0,
    disponibilidad_habitaciones: 0,
    consultoria: 0,
    analitica_dataset: 0,
    memoria_usuario: 0,
    documental: 0
  };

  // =========================
  // 1. Señales de reserva
  // =========================

  const patronesReserva = [
    "quiero reservar",
    "deseo reservar",
    "necesito reservar",
    "me gustaria reservar",
    "reservar una habitacion",
    "reservar la habitacion",
    "hacer una reserva",
    "crear una reserva",
    "registrar una reserva",
    "separar una habitacion",
    "apartar una habitacion",
    "reservame",
    "reserva una",
    "reserva la"
  ];

  const regexReserva = [
    /\breserv(ar|a|ame|acion|aciones)\b/,
    /\b(apartar|separar)\b.*\bhabitacion\b/,
    /\bquiero\b.*\bhabitacion\b.*\bpara\b.*\bpersona/,
    /\bhabitacion\s+[a-z]-\d{3}\b.*\bpara\b.*\bpersona/
  ];

  if (contieneAlguno(pregunta, patronesReserva)) score.reserva_simulada += 3;
  if (coincideAlguno(pregunta, regexReserva)) score.reserva_simulada += 3;

  // Si menciona noches/personas junto con intención de habitación, suma a reserva.
  if (/\b(\d+|una|un|uno|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)\s+(noche|noches|dia|dias)\b/.test(pregunta)) {
    score.reserva_simulada += 1;
  }

  if (/\bpara\s+(\d+|una|un|uno|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)\s+(persona|personas|huesped|huespedes|adulto|adultos)\b/.test(pregunta)) {
    score.reserva_simulada += 1;
  }

  // =========================
  // 2. Señales de disponibilidad
  // =========================

  const patronesDisponibilidad = [
    "hay disponibilidad",
    "tienen disponibilidad",
    "habitaciones disponibles",
    "habitacion disponible",
    "cuantas habitaciones",
    "que habitaciones hay",
    "consultar disponibilidad",
    "ver disponibilidad",
    "disponibilidad de habitaciones",
    "hay habitaciones"
  ];

  if (contieneAlguno(pregunta, patronesDisponibilidad)) {
    score.disponibilidad_habitaciones += 4;
  }

  if (/\b(disponible|disponibles|disponibilidad)\b/.test(pregunta)) {
    score.disponibilidad_habitaciones += 2;
  }

  // =========================
  // 3. Señales de memoria de usuario
  // =========================

  const patronesMemoria = [
    "me llamo",
    "mi nombre es",
    "soy ",
    "prefiero",
    "me gusta",
    "no me gusta",
    "me encantan",
    "me interesa",
    "recuerda que",
    "quiero que recuerdes",
    "ten en cuenta",
    "viajo con",
    "viajamos",
    "somos",
    "mi presupuesto",
    "presupuesto maximo",
    "presupuesto es",
    "tengo un presupuesto",
    "habitaciones tranquilas",
    "habitacion tranquila",
    "vista al patio",
    "vista al hotel",
    "patio colonial",
    "vista exterior",
    "vista interior"
  ];

  const regexMemoria = [
    /\bme llamo\s+[a-zñ]+/i,
    /\bmi nombre es\s+[a-zñ]+/i,
    /\bsoy\s+[a-zñ]+/i,
    /\bprefiero\b/,
    /\bpreferimos\b/,
    /\bme gusta\b/,
    /\bno me gusta\b/,
    /\brecuerda que\b/,
    /\bten en cuenta\b/,
    /\bsomos\s+\d+\s+(adultos|personas|huespedes)\b/,
    /\b\d+\s+adultos?\b/,
    /\b\d+\s+ninos?\b/,
    /\b\d+\s+niños?\b/,
    /\bpresupuesto\b/,
    /\b\d{5,9}\s*(cop|pesos)?\b.*\b(noche|habitacion|presupuesto)\b/,
    /\b(sencilla|doble|triple|familiar|suite)\b.*\b(comoda|tranquila|preferida|prefiero)\b/,
    /\b(vista|patio colonial|hotel)\b/
  ];

  if (contieneAlguno(pregunta, patronesMemoria)) score.memoria_usuario += 3;
  if (coincideAlguno(pregunta, regexMemoria)) score.memoria_usuario += 3;

  // Frases típicas de memoria sin intención de reservar.
  if (pregunta.startsWith("prefiero") || pregunta.startsWith("me llamo") || pregunta.startsWith("mi presupuesto") || pregunta.startsWith("somos")) {
    score.memoria_usuario += 3;
  }

  // =========================
  // 4. Señales documentales
  // =========================

  const patronesDocumental = [
    "politicas",
    "politica",
    "check in",
    "check-in",
    "check out",
    "check-out",
    "hora de entrada",
    "hora de salida",
    "desayuno",
    "mascotas",
    "cancelacion",
    "cancelar",
    "normas",
    "reglas",
    "servicios del hotel",
    "wifi",
    "parqueadero",
    "ubicacion",
    "direccion",
    "telefono",
    "contacto"
  ];

  if (contieneAlguno(pregunta, patronesDocumental)) {
    score.documental += 3;
  }

  // =========================
  // 5. Señales de analítica/dataset
  // =========================

  const patronesAnalitica = [
    "dataset",
    "metricas",
    "estadisticas",
    "promedio",
    "grafica",
    "grafico",
    "analisis",
    "analitica",
    "cuantas reservas",
    "habitaciones mas reservadas",
    "ocupacion",
    "reporte"
  ];

  if (contieneAlguno(pregunta, patronesAnalitica)) {
    score.analitica_dataset += 4;
  }

  // =========================
  // 6. Señales de consultoría
  // =========================

  const patronesConsultoria = [
    "que me recomiendas",
    "cual me recomiendas",
    "recomiendame",
    "que habitacion es mejor",
    "cual habitacion es mejor",
    "que opcion es mejor",
    "consejo",
    "sugerencia"
  ];

  if (contieneAlguno(pregunta, patronesConsultoria)) {
    score.consultoria += 3;
  }

  // =========================
  // 7. Fuera de alcance
  // =========================

  const senalesHotel =
    score.reserva_simulada > 0 ||
    score.disponibilidad_habitaciones > 0 ||
    score.memoria_usuario > 0 ||
    score.documental > 0 ||
    score.analitica_dataset > 0 ||
    score.consultoria > 0;

  if (!senalesHotel) {
    score.fuera_alcance += 2;
  }

  // =========================
  // 8. Reglas de prioridad
  // =========================

  let tipoSolicitud = "fuera_alcance";
  let motivoClasificacion = "La pregunta no coincide con las funciones disponibles del asistente.";
  let confianzaClasificacion = "baja";

  // Prioridad 1: reserva explícita.
  // Si el usuario dice reservar/apartar/separar, se respeta como reserva aunque incluya preferencias.
  if (score.reserva_simulada >= 4) {
    tipoSolicitud = "reserva_simulada";
    motivoClasificacion = "La pregunta expresa una intención clara de registrar una reserva.";
    confianzaClasificacion = "alta";
  }

  // Prioridad 2: disponibilidad.
  else if (score.disponibilidad_habitaciones >= 4) {
    tipoSolicitud = "disponibilidad_habitaciones";
    motivoClasificacion = "La pregunta solicita consultar disponibilidad de habitaciones.";
    confianzaClasificacion = "alta";
  }

  // Prioridad 3: memoria de usuario.
  else if (score.memoria_usuario >= 3) {
    tipoSolicitud = "memoria_usuario";
    motivoClasificacion = "La pregunta contiene información personal, preferencias o datos útiles para recordar.";
    confianzaClasificacion = score.memoria_usuario >= 6 ? "alta" : "media";
  }

  // Prioridad 4: analítica.
  else if (score.analitica_dataset >= 4) {
    tipoSolicitud = "analitica_dataset";
    motivoClasificacion = "La pregunta solicita métricas, estadísticas o análisis del dataset.";
    confianzaClasificacion = "alta";
  }

  // Prioridad 5: documental.
  else if (score.documental >= 3) {
    tipoSolicitud = "documental";
    motivoClasificacion = "La pregunta solicita información documental o políticas del hotel.";
    confianzaClasificacion = "media";
  }

  // Prioridad 6: consultoría.
  else if (score.consultoria >= 3) {
    tipoSolicitud = "consultoria";
    motivoClasificacion = "La pregunta solicita recomendación o asesoría sobre opciones del hotel.";
    confianzaClasificacion = "media";
  }

  return {
    json: {
      ...data,
      pregunta_original: data.pregunta_original || preguntaOriginal,
      pregunta_normalizada: pregunta,
      pregunta_valida: Boolean(data.pregunta_valida ?? true),
      longitud_pregunta: preguntaOriginal.length,

      tipo_solicitud: tipoSolicitud,
      confianza_clasificacion: confianzaClasificacion,
      motivo_clasificacion: motivoClasificacion,
      score_clasificacion: score
    }
  };
});

const items = $input.all();

function limpiarRespuesta(texto) {
  let respuesta = String(texto || "").trim();

  respuesta = respuesta
    .replace(/Espero que esta información te sea útil\.?/gi, "")
    .replace(/¿Tienes alguna otra pregunta\?/gi, "")
    .replace(/Tienes alguna otra pregunta\?/gi, "")
    .replace(/Estoy aquí para ayudarte\.?/gi, "")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .trim();

  return respuesta || "No se generó una respuesta del agente.";
}

return items.map((item) => {
  const respuestaOriginal =
    item.json.output ||
    item.json.text ||
    item.json.response ||
    "No se generó una respuesta del agente.";

  const respuesta = limpiarRespuesta(respuestaOriginal);

  return {
    json: {
      tipo_solicitud: $("Code - Clasificar Intención").item.json.tipo_solicitud,
      pregunta_usuario: $("Edit Fields").item.json.pregunta_usuario,
      pregunta_normalizada: $("Code - Normalizar Pregunta").item.json.pregunta_normalizada,
      nombre_hotel: $("Edit Fields").item.json.nombre_hotel,
      modelo_usado: "llama3:latest",
      fuente: "Documento_Base_Hotel.md desde GitHub RAW",
      respuesta_final: respuesta,
      estado: "completado",
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const tipo = item.json.tipo_solicitud || "fuera_alcance";
  const pregunta = item.json.pregunta_usuario || item.json.pregunta_original || "";

  let respuesta = "";

  if (tipo === "fuera_alcance") {
    respuesta = "No puedo proporcionar contraseñas, credenciales, datos privados, información interna sensible ni instrucciones que comprometan la seguridad del sistema o del hotel.";
  } else if (tipo === "disponibilidad_habitaciones") {
    respuesta = "Todavía no tengo conectado el módulo de disponibilidad real de habitaciones. En la siguiente versión podré consultar habitaciones disponibles, ocupadas y capacidad por tipo de habitación.";
  } else if (tipo === "consultoria") {
    respuesta = "Todavía no tengo conectado el módulo de consultoría hotelera. En una siguiente versión podré recomendar habitaciones según número de personas, preferencias, presupuesto y disponibilidad.";
  } else if (tipo === "memoria_usuario") {
    respuesta = "He detectado información que podría usarse como preferencia del usuario, pero el módulo de memoria personalizada todavía no está habilitado en esta versión.";
  } else {
    respuesta = "No puedo procesar esta solicitud con los módulos disponibles actualmente.";
  }

  return {
    json: {
      tipo_solicitud: tipo,
      pregunta_usuario: pregunta,
      pregunta_normalizada: item.json.pregunta_normalizada || "",
      nombre_hotel: item.json.nombre_hotel || "Hotel El Claustro de San Francisco",
      motivo_clasificacion: item.json.motivo_clasificacion || "",
      respuesta_final: respuesta,
      estado: tipo === "fuera_alcance" ? "rechazado_fuera_de_alcance" : "modulo_pendiente",
      fuente: "Reglas internas del workflow",
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();

const numerosTexto = {
  "una": 1,
  "un": 1,
  "uno": 1,
  "dos": 2,
  "tres": 3,
  "cuatro": 4,
  "cinco": 5,
  "seis": 6,
  "siete": 7,
  "ocho": 8,
  "nueve": 9,
  "diez": 10
};

function convertirNumero(valor) {
  if (!valor) return null;

  const limpio = valor.toString().toLowerCase().trim();

  if (!isNaN(Number(limpio))) return Number(limpio);

  return numerosTexto[limpio] || null;
}

function extraerCodigoHabitacion(texto) {
  const textoUpper = String(texto || "").toUpperCase();

  // Detecta códigos como:
  // D-007, D007, SU-005, SU005, T-010, S-001, F-003
  const match = textoUpper.match(/\b(SU|D|T|S|F)\s*-?\s*(\d{1,3})\b/);

  if (!match) {
    return null;
  }

  const prefijo = match[1];
  const numero = match[2].padStart(3, "0");

  return `${prefijo}-${numero}`;
}

function inferirTipoPorCodigo(codigo) {
  if (!codigo) return null;

  const prefijo = codigo.split("-")[0];

  const mapa = {
    S: "sencilla",
    D: "doble",
    T: "triple",
    SU: "suite",
    F: "familiar"
  };

  return mapa[prefijo] || null;
}

function convertirTipoVisible(tipoDb) {
  const mapa = {
    sencilla: "habitación sencilla",
    doble: "habitación doble",
    triple: "habitación triple",
    familiar: "habitación familiar",
    suite: "suite"
  };

  return mapa[tipoDb] || null;
}

return items.map((item) => {
  const preguntaOriginal = item.json.pregunta_usuario || item.json.pregunta_original || "";
  const pregunta = item.json.pregunta_normalizada || preguntaOriginal.toLowerCase();

  const codigoHabitacionSolicitado = extraerCodigoHabitacion(
    pregunta || preguntaOriginal
  );

  const tipoInferidoPorCodigo = inferirTipoPorCodigo(codigoHabitacionSolicitado);

  let tipoHabitacion = null;
  let tipoHabitacionDb = null;

  if (pregunta.includes("sencilla")) {
    tipoHabitacion = "habitación sencilla";
    tipoHabitacionDb = "sencilla";
  } else if (pregunta.includes("doble")) {
    tipoHabitacion = "habitación doble";
    tipoHabitacionDb = "doble";
  } else if (pregunta.includes("triple")) {
    tipoHabitacion = "habitación triple";
    tipoHabitacionDb = "triple";
  } else if (pregunta.includes("familiar")) {
    tipoHabitacion = "habitación familiar";
    tipoHabitacionDb = "familiar";
  } else if (pregunta.includes("suite")) {
    tipoHabitacion = "suite";
    tipoHabitacionDb = "suite";
  }

  // Si el usuario no dijo "doble", "suite", etc.,
  // pero sí dijo un código como D-007, inferimos el tipo desde el código.
  if (!tipoHabitacionDb && tipoInferidoPorCodigo) {
    tipoHabitacionDb = tipoInferidoPorCodigo;
    tipoHabitacion = convertirTipoVisible(tipoInferidoPorCodigo);
  }

  const matchNoches = pregunta.match(/(\d+|una|un|uno|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)\s+(noche|noches|dia|dias)/);
  const numeroNoches = matchNoches ? convertirNumero(matchNoches[1]) : null;

  const matchPersonas = pregunta.match(/para\s+(\d+|una|un|uno|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)\s+(persona|personas|huesped|huespedes|adulto|adultos)/);
  const numeroPersonas = matchPersonas ? convertirNumero(matchPersonas[1]) : null;

  const matchFechaISO = pregunta.match(/\b(20\d{2}-\d{2}-\d{2})\b/);
  const matchFechaLatam = pregunta.match(/\b(\d{1,2}\/\d{1,2}\/20\d{2})\b/);

  let fechaEntrada = null;

  if (matchFechaISO) fechaEntrada = matchFechaISO[1];
  else if (matchFechaLatam) fechaEntrada = matchFechaLatam[1];
  else if (pregunta.includes("manana")) fechaEntrada = "mañana";
  else if (pregunta.includes("mañana")) fechaEntrada = "mañana";
  else if (pregunta.includes("hoy")) fechaEntrada = "hoy";

  const datosFaltantes = [];

  // Antes exigíamos siempre tipo de habitación.
  // Ahora aceptamos tipo de habitación O código de habitación.
  if (!tipoHabitacionDb && !codigoHabitacionSolicitado) {
    datosFaltantes.push("tipo de habitación o código de habitación");
  }

  if (!numeroNoches) datosFaltantes.push("número de noches");
  if (!numeroPersonas) datosFaltantes.push("número de personas");
  if (!fechaEntrada) datosFaltantes.push("fecha de entrada");

  const reservaCompleta = datosFaltantes.length === 0;

  return {
    json: {
      ...item.json,

      tipo_habitacion: tipoHabitacion,
      tipo_habitacion_db: tipoHabitacionDb,

      codigo_habitacion_solicitado: codigoHabitacionSolicitado,
      tipo_habitacion_inferida_codigo: tipoInferidoPorCodigo,

      numero_noches: numeroNoches,
      numero_personas: numeroPersonas,
      fecha_entrada: fechaEntrada,

      datos_faltantes: datosFaltantes,
      reserva_completa: reservaCompleta,
      estado_extraccion_reserva: reservaCompleta ? "datos_completos" : "faltan_datos"
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const faltantes = item.json.datos_faltantes || [];

  return {
    json: {
      tipo_solicitud: "reserva_simulada",
      pregunta_usuario: item.json.pregunta_usuario || item.json.pregunta_original || "",
      nombre_hotel: item.json.nombre_hotel || "Hotel El Claustro de San Francisco",
      tipo_habitacion: item.json.tipo_habitacion,
      numero_noches: item.json.numero_noches,
      numero_personas: item.json.numero_personas,
      fecha_entrada: item.json.fecha_entrada,
      datos_faltantes: faltantes,
      respuesta_final: `Para simular la reserva necesito que me indiques: ${faltantes.join(", ")}.`,
      estado: "reserva_pendiente_datos",
      fuente: "Reglas internas de simulación de reserva",
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();

function formatoNumero(valor) {
  if (valor === null || valor === undefined || valor === "") return "no disponible";
  const numero = Number(valor);
  if (Number.isNaN(numero)) return valor.toString();
  return numero.toLocaleString("es-CO");
}

function formatoDecimal(valor) {
  if (valor === null || valor === undefined || valor === "") return "no disponible";
  const numero = Number(valor);
  if (Number.isNaN(numero)) return valor.toString();
  return numero.toLocaleString("es-CO", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

return items.map((item) => {
  const pregunta = $("Code - Clasificar Intención").item.json.pregunta_normalizada || "";
  const preguntaUsuario = $("Edit Fields").item.json.pregunta_usuario || "";
  const nombreHotel = $("Edit Fields").item.json.nombre_hotel || "Hotel El Claustro de San Francisco";
  const m = item.json;

  let respuesta = "";

  if (pregunta.includes("tasa de cancelacion") || pregunta.includes("porcentaje de cancelacion") || pregunta.includes("cancelaciones")) {
    respuesta =
      `Según el dataset histórico, la tasa global de cancelación es de ${formatoDecimal(m.tasa_cancelacion_porcentaje)}%. ` +
      `Para City Hotel es de ${formatoDecimal(m.cancelacion_city_hotel)}% y para Resort Hotel es de ${formatoDecimal(m.cancelacion_resort_hotel)}%.`;
  } else if (pregunta.includes("adr") || pregunta.includes("precio promedio")) {
    respuesta =
      `Según el dataset histórico, el ADR promedio registrado es de ${formatoDecimal(m.adr_promedio)}.`;
  } else if (pregunta.includes("lead time") || pregunta.includes("anticipacion")) {
    respuesta =
      `Según el dataset histórico, el lead time promedio es de ${formatoDecimal(m.lead_time_promedio)} días.`;
  } else if (pregunta.includes("mes") && pregunta.includes("reservas")) {
    respuesta =
      `Según el dataset histórico, el mes con más reservas es ${m.mes_mas_reservas}.`;
  } else if (pregunta.includes("segmento")) {
    respuesta =
      `Según el dataset histórico, el segmento de mercado más frecuente es ${m.segmento_mas_frecuente}.`;
  } else if (pregunta.includes("city hotel") || pregunta.includes("resort hotel") || pregunta.includes("hotel con mas reservas")) {
    respuesta =
      `Según el dataset histórico, City Hotel registra ${formatoNumero(m.reservas_city_hotel)} reservas y Resort Hotel registra ${formatoNumero(m.reservas_resort_hotel)} reservas.`;
  } else {
    respuesta =
      `Resumen analítico del dataset: total de reservas ${formatoNumero(m.total_reservas)}, ` +
