  "ocho": 8,
  "nueve": 9,
  "diez": 10
};

function quitarTildes(texto) {
  return String(texto ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function normalizarTexto(texto) {
  return quitarTildes(texto)
    .toLowerCase()
    .replace(/[¿?¡!]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function sqlText(valor) {
  return String(valor ?? "")
    .replace(/'/g, "''")
    .trim();
}

function convertirNumero(valor) {
  if (valor === null || valor === undefined) return null;

  const limpio = normalizarTexto(valor);

  if (!Number.isNaN(Number(limpio))) {
    return Number(limpio);
  }

  return numerosTexto[limpio] ?? null;
}

function capitalizarNombre(nombre) {
  if (!nombre) return null;

  return nombre
    .split(" ")
    .filter(Boolean)
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase())
    .join(" ");
}

function extraerNombre(pregunta) {
  const patrones = [
    /\bme llamo\s+([a-zñáéíóú]+(?:\s+[a-zñáéíóú]+){0,3})(?=\s+(?:y|prefiero|quiero|busco|viajo|somos|tengo|mi|con)|[.,;]|$)/i,
    /\bmi nombre es\s+([a-zñáéíóú]+(?:\s+[a-zñáéíóú]+){0,3})(?=\s+(?:y|prefiero|quiero|busco|viajo|somos|tengo|mi|con)|[.,;]|$)/i,
    /\bsoy\s+([a-zñáéíóú]+(?:\s+[a-zñáéíóú]+){0,2})(?=\s+(?:y|prefiero|quiero|busco|viajo|somos|tengo|mi|con)|[.,;]|$)/i
  ];

  for (const patron of patrones) {
    const match = pregunta.match(patron);
    if (match && match[1]) {
      const nombre = match[1].trim();

      const descartados = [
        "adulto",
        "adultos",
        "nino",
        "ninos",
        "niño",
        "niños",
        "persona",
        "personas",
        "huesped",
        "huespedes",
        "huésped",
        "huéspedes"
      ];

      if (!descartados.includes(normalizarTexto(nombre))) {
        return capitalizarNombre(nombre);
      }
    }
  }

  return null;
}

