  const grupoPalabras = palabras.join("|");
  const patron = new RegExp(
    `\\b(\\d+|una|un|uno|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)\\s+(${grupoPalabras})\\b`,
    "i"
  );

  const match = pregunta.match(patron);

  if (!match) return null;

  return convertirNumero(match[1]);
}

function extraerPresupuesto(preguntaOriginal, preguntaNormalizada) {
  let texto = preguntaOriginal || "";
  let textoNorm = preguntaNormalizada || normalizarTexto(texto);

  const patrones = [
    /(?:presupuesto|maximo|maxima|máximo|máxima|hasta|tope|pagar|menos de)[^\d]{0,25}(\$?\s*\d[\d.\s]*)/i,
    /(\$?\s*\d[\d.\s]*)\s*(?:cop|pesos)?\s*(?:por noche|la noche|noche)/i
  ];

  for (const patron of patrones) {
    const match = texto.match(patron);
    if (match && match[1]) {
      const limpio = match[1]
        .replace(/\$/g, "")
        .replace(/\./g, "")
        .replace(/\s/g, "")
        .trim();

      const numero = Number(limpio);
      if (!Number.isNaN(numero) && numero > 0) {
        return numero;
      }
    }
  }

  const matchMil = textoNorm.match(/(?:presupuesto|hasta|maximo|tope|pagar|menos de)[^\d]{0,25}(\d+)\s*mil/);
  if (matchMil && matchMil[1]) {
    return Number(matchMil[1]) * 1000;
  }

  return null;
}

function extraerTipoHabitacionPreferida(pregunta) {
  if (pregunta.includes("suite")) return "suite";
  if (pregunta.includes("familiar")) return "familiar";
  if (pregunta.includes("triple")) return "triple";
  if (pregunta.includes("doble")) return "doble";
  if (pregunta.includes("sencilla") || pregunta.includes("simple") || pregunta.includes("individual")) return "sencilla";

