  if (pregunta.includes("vista premium")) return "vista premium al hotel";
  if (pregunta.includes("vista al mar")) return "vista al mar";
  if (pregunta.includes("vista exterior")) return "vista exterior";
  if (pregunta.includes("vista interior")) return "vista interior";

  const matchVista = pregunta.match(/\bvista\s+(?:a|al|hacia|para)?\s*([a-zñáéíóú\s]{3,40})(?=,|\.|;|\sy\s|\scon\s|$)/i);
  if (matchVista && matchVista[1]) {
    return matchVista[1].trim();
