function extraerTextoModelo(itemJson) {
  if (typeof itemJson.output === "string") return itemJson.output;
  if (typeof itemJson.text === "string") return itemJson.text;
  if (typeof itemJson.response === "string") return itemJson.response;

  if (
    itemJson.response &&
    itemJson.response.generations &&
    itemJson.response.generations[0] &&
    itemJson.response.generations[0][0] &&
    typeof itemJson.response.generations[0][0].text === "string"
  ) {
    return itemJson.response.generations[0][0].text;
  }

  return JSON.stringify(itemJson);
}

function normalizarSalidaCruda(texto) {
  let salida = String(texto ?? "").trim();

  salida = salida
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  // Intento de decodificación si viene como string JSON.
  for (let i = 0; i < 3; i++) {
    if (
      (salida.startsWith('"') && salida.endsWith('"')) ||
      (salida.startsWith("'") && salida.endsWith("'"))
    ) {
      try {
        salida = JSON.parse(salida);
      } catch (error) {
        salida = salida.slice(1, -1);
      }
    }
  }

  salida = salida
    .replace(/\\n/g, "\n")
    .replace(/\\r/g, "")
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, "\\")
    .trim();

  return salida;
}

function extraerBloqueJson(texto) {
  const limpio = normalizarSalidaCruda(texto);
  const inicio = limpio.indexOf("{");
  const fin = limpio.lastIndexOf("}");

  if (inicio !== -1 && fin !== -1 && fin > inicio) {
    return limpio.slice(inicio, fin + 1).trim();
  }

  return limpio;
}

function parsearJsonEstricto(texto) {
  const bloque = extraerBloqueJson(texto);

  try {
    return {
      ok: true,
      data: JSON.parse(bloque),
      texto_limpio: bloque,
      metodo: "json_parse",
      error: null
    };
  } catch (error) {
    return {
      ok: false,
      data: {},
      texto_limpio: bloque,
      metodo: "json_parse_fallido",
      error: error.message
    };
  }
}

function extraerStringPorClave(texto, clave) {
  const regex = new RegExp(`"${clave}"\\s*:\\s*(null|"((?:\\\\.|[^"\\\\])*)")`, "i");
  const match = texto.match(regex);

  if (!match) return null;
  if (match[1] === "null") return null;

  return String(match[2] ?? "")
    .replace(/\\"/g, '"')
    .replace(/\\n/g, "\n")
    .trim();
}

function extraerNumeroPorClave(texto, clave) {
  const regex = new RegExp(`"${clave}"\\s*:\\s*(null|-?\\d+(?:\\.\\d+)?)`, "i");
  const match = texto.match(regex);

  if (!match) return null;
  if (match[1] === "null") return null;

  const numero = Number(match[1]);
  return Number.isFinite(numero) ? numero : null;
}

function extraerBooleanPorClave(texto, clave) {
  const regex = new RegExp(`"${clave}"\\s*:\\s*(true|false|"true"|"false")`, "i");
  const match = texto.match(regex);

  if (!match) return false;

  return String(match[1]).replace(/"/g, "").toLowerCase() === "true";
}

function extraerArrayStringsPorClave(texto, clave) {
  const regex = new RegExp(`"${clave}"\\s*:\\s*\\[([\\s\\S]*?)\\]`, "i");
  const match = texto.match(regex);

  if (!match) return [];

  const contenido = match[1];
  const valores = [...contenido.matchAll(/"([^"]+)"/g)].map((m) => m[1].trim());

  return valores.filter(Boolean);
}

function parsearJsonConRespaldo(texto) {
  const estricto = parsearJsonEstricto(texto);

  if (estricto.ok) return estricto;

  const limpio = extraerBloqueJson(texto);

  const data = {
    memoria_detectada: extraerBooleanPorClave(limpio, "memoria_detectada"),
    nombre_usuario: extraerStringPorClave(limpio, "nombre_usuario"),
    numero_adultos: extraerNumeroPorClave(limpio, "numero_adultos"),
    numero_ninos: extraerNumeroPorClave(limpio, "numero_ninos"),
    tipo_habitacion_preferida: extraerStringPorClave(limpio, "tipo_habitacion_preferida"),
    vista_preferida: extraerStringPorClave(limpio, "vista_preferida"),
    presupuesto_max_cop: extraerNumeroPorClave(limpio, "presupuesto_max_cop"),
    preferencias_texto: extraerStringPorClave(limpio, "preferencias_texto"),
    campos_detectados: extraerArrayStringsPorClave(limpio, "campos_detectados"),
    confianza_extraccion: extraerStringPorClave(limpio, "confianza_extraccion")
  };

  const hayAlgo =
    data.memoria_detectada ||
    data.nombre_usuario ||
    data.numero_adultos !== null ||
    data.numero_ninos !== null ||
    data.tipo_habitacion_preferida ||
    data.vista_preferida ||
    data.presupuesto_max_cop !== null ||
    data.preferencias_texto ||
    data.campos_detectados.length > 0;

  return {
    ok: hayAlgo,
    data,
    texto_limpio: limpio,
    metodo: hayAlgo ? "regex_fallback" : "fallo_total",
    error: estricto.error
  };
}

function normalizarTexto(valor) {
  return String(valor ?? "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function sqlText(valor) {
  return String(valor ?? "")
    .replace(/'/g, "''")
    .trim();
}

function enteroONull(valor) {
  if (valor === null || valor === undefined || valor === "") return null;

  const numero = Number(valor);
  if (!Number.isFinite(numero)) return null;

  return Math.trunc(numero);
}

function dineroONull(valor) {
  if (valor === null || valor === undefined || valor === "") return null;

  if (typeof valor === "number") {
    return Number.isFinite(valor) ? valor : null;
  }

  const limpio = String(valor)
    .replace(/\s/g, "")
    .replace(/COP/gi, "")
    .replace(/\$/g, "")
    .replace(/\./g, "")
    .replace(/,/g, "")
    .replace(/[^\d]/g, "");

  if (!limpio) return null;

  const numero = Number(limpio);
  return Number.isFinite(numero) ? numero : null;
}

function normalizarTipoHabitacion(valor) {
  if (!valor) return null;

  const texto = normalizarTexto(valor);

  if (texto.includes("sencilla") || texto.includes("individual")) return "sencilla";
  if (texto.includes("doble")) return "doble";
  if (texto.includes("triple")) return "triple";
  if (texto.includes("familiar")) return "familiar";
  if (texto.includes("suite")) return "suite";

  return null;
}

function normalizarVista(valor) {
  if (!valor) return null;

  const texto = normalizarTexto(valor);

  if (texto.includes("patio")) return "patio colonial";
  if (texto.includes("premium")) return "vista premium al hotel";
  if (texto.includes("hotel")) return "vista al hotel";
  if (texto.includes("exterior")) return "vista exterior";
  if (texto.includes("interior")) return "vista interior";

  return String(valor).trim();
}

function normalizarConfianza(valor) {
  const texto = normalizarTexto(valor);

  if (texto === "alta") return "alta";
  if (texto === "media") return "media";
  if (texto === "baja") return "baja";

  return "media";
}

function limpiarCamposDetectados(campos) {
  const permitidos = [
    "nombre_usuario",
    "numero_adultos",
    "numero_ninos",
    "tipo_habitacion_preferida",
    "vista_preferida",
    "presupuesto_max_cop",
    "preferencias_texto"
  ];

  if (!Array.isArray(campos)) return [];

  return [...new Set(
    campos
      .map((campo) => String(campo ?? "").trim())
      .filter((campo) => permitidos.includes(campo))
  )];
}

function inferirCamposDetectados(memoriaNormalizada) {
  const campos = [];

  if (memoriaNormalizada.nombre_usuario) campos.push("nombre_usuario");
  if (memoriaNormalizada.numero_adultos !== null) campos.push("numero_adultos");
  if (memoriaNormalizada.numero_ninos !== null) campos.push("numero_ninos");
  if (memoriaNormalizada.tipo_habitacion_preferida) campos.push("tipo_habitacion_preferida");
  if (memoriaNormalizada.vista_preferida) campos.push("vista_preferida");
  if (memoriaNormalizada.presupuesto_max_cop !== null) campos.push("presupuesto_max_cop");
  if (memoriaNormalizada.preferencias_texto) campos.push("preferencias_texto");

  return campos;
}

