const items = $input.all();

function texto(valor) {
  if (valor === null || valor === undefined) return null;

  const limpio = String(valor).trim();
  if (!limpio) return null;

  const normalizado = limpio.toLowerCase();

  if (
    normalizado === "null" ||
    normalizado === "undefined" ||
    normalizado === "nan" ||
    normalizado === "none"
  ) {
    return null;
  }

  return limpio;
}

function sqlText(valor) {
  return String(valor ?? "")
    .replace(/'/g, "''")
    .trim();
}

function primerValorUtil(...valores) {
  for (const valor of valores) {
    const t = texto(valor);
    if (t !== null) return valor;
  }

  return null;
}

function entero(valor) {
  const t = texto(valor);
  if (!t) return null;

  const limpio = String(t).replace(/[^\d.-]/g, "");
  const n = Number(limpio);

  if (!Number.isFinite(n)) return null;

  const numeroEntero = Math.trunc(n);
  return numeroEntero > 0 ? numeroEntero : null;
}

function numeroCOP(valor) {
  const t = texto(valor);
  if (!t) return null;

  if (typeof valor === "number") {
    return Number.isFinite(valor) && valor > 0 ? valor : null;
  }

  let limpio = String(t)
    .toLowerCase()
    .replace(/cop/g, "")
    .replace(/\$/g, "")
    .replace(/\s+/g, "")
    .replace(/[^\d.,-]/g, "");

  if (!limpio) return null;

  const tieneComa = limpio.includes(",");
  const tienePunto = limpio.includes(".");

  if (tieneComa && tienePunto) {
    const ultimaComa = limpio.lastIndexOf(",");
    const ultimoPunto = limpio.lastIndexOf(".");

    if (ultimaComa > ultimoPunto) {
      limpio = limpio.replace(/\./g, "").replace(",", ".");
    } else {
      limpio = limpio.replace(/,/g, "");
    }
  } else if (tienePunto && !tieneComa) {
    const partes = limpio.split(".");

    if (partes.length > 2 || partes[partes.length - 1].length === 3) {
      limpio = limpio.replace(/\./g, "");
    }
  } else if (tieneComa && !tienePunto) {
    const partes = limpio.split(",");

    if (partes.length > 2 || partes[partes.length - 1].length === 3) {
      limpio = limpio.replace(/,/g, "");
    } else {
      limpio = limpio.replace(",", ".");
    }
  }

  const n = Number(limpio);

  if (!Number.isFinite(n)) return null;

  return n > 0 ? n : null;
}

function normalizarBase(valor) {
  const t = texto(valor);
  if (!t) return null;

  return t
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function normalizarTipoHabitacion(valor) {
  const limpio = normalizarBase(valor);
  if (!limpio) return null;

  if (
    limpio.includes("sencilla") ||
    limpio.includes("simple") ||
    limpio.includes("individual")
  ) {
    return "sencilla";
  }

  if (
    limpio.includes("doble") ||
    limpio.includes("pareja") ||
    limpio.includes("matrimonial")
  ) {
    return "doble";
  }

  if (limpio.includes("triple")) {
    return "triple";
  }

  if (
    limpio.includes("familiar") ||
    limpio.includes("familia") ||
    limpio.includes("grupo")
  ) {
    return "familiar";
  }

  if (limpio.includes("suite")) {
    return "suite";
  }

  const permitidos = ["sencilla", "doble", "triple", "familiar", "suite"];
  return permitidos.includes(limpio) ? limpio : null;
}

function tipoDesdeCodigoHabitacion(codigo) {
  const c = texto(codigo);
  if (!c) return null;

  const normalizado = c.toUpperCase().trim();

  if (normalizado.startsWith("S-")) return "sencilla";
  if (normalizado.startsWith("D-")) return "doble";
  if (normalizado.startsWith("T-")) return "triple";
  if (normalizado.startsWith("F-")) return "familiar";
  if (normalizado.startsWith("SU-")) return "suite";

  return null;
}

function extraerCodigoHabitacionDesdeTexto(...textos) {
  const combinado = textos
    .map((t) => texto(t))
    .filter(Boolean)
    .join(" ");

  if (!combinado) return null;

  const match = combinado.match(/\b([A-Za-z]{1,3})\s*[-]\s*(\d{1,4})\b/);

  if (!match) return null;

  const prefijo = match[1].toUpperCase();
  const numero = match[2].padStart(3, "0");

  return `${prefijo}-${numero}`;
}

function tipoHabitacionTexto(tipoDb, codigoHabitacion) {
  if (tipoDb) {
    if (tipoDb === "suite") return "suite";
    return `habitación ${tipoDb}`;
  }

  if (codigoHabitacion) {
    return `habitación ${codigoHabitacion}`;
  }

  return null;
}

function normalizarVista(valor) {
  const limpio = normalizarBase(valor);
  if (!limpio) return null;

  if (limpio.includes("patio") || limpio.includes("colonial")) {
    return "patio colonial";
  }

  if (limpio.includes("calle")) {
    return "calle";
  }

  if (limpio.includes("jardin")) {
    return "jardín";
  }

  if (limpio.includes("ciudad")) {
    return "ciudad";
  }

  if (limpio.includes("interior")) {
    return "interior";
  }

  return texto(valor);
}

