function obtenerJsonNodo(nombreNodo) {
  try {
    const datos = $(nombreNodo).all();
    if (Array.isArray(datos) && datos.length > 0 && datos[0].json) {
      return datos[0].json;
    }
  } catch (error) {}

  try {
    const dato = $(nombreNodo).item.json;
    if (dato) return dato;
  } catch (error) {}

  return {};
}

function tomar(...valores) {
  for (const valor of valores) {
    if (valor !== undefined && valor !== null && valor !== "") {
      return valor;
    }
  }
  return null;
}

function numero(valor) {
  if (valor === undefined || valor === null || valor === "") return null;

  if (typeof valor === "number") {
    return Number.isFinite(valor) ? valor : null;
  }

  const limpio = String(valor)
    .replace(/[^\d.,-]/g, "")
    .replace(/\.(?=\d{3}(\D|$))/g, "")
    .replace(",", ".");

  const n = Number(limpio);
  return Number.isFinite(n) ? n : null;
}

function entero(valor) {
  const n = numero(valor);
  return n === null ? null : Math.trunc(n);
}

function dineroCOP(valor) {
  const n = numero(valor);

  if (n === null) {
    return "no disponible";
  }

  return n.toLocaleString("es-CO", {
    style: "currency",
    currency: "COP",
    maximumFractionDigits: 0
  });
}

function textoPersonas(cantidad) {
  const n = entero(cantidad);
  if (n === null) return null;
  return n === 1 ? "1 persona" : `${n} personas`;
}

function textoNoches(cantidad) {
  const n = entero(cantidad);
  if (n === null) return null;
  return n === 1 ? "1 noche" : `${n} noches`;
}

