    datosExtraidosReserva.tipo_habitacion
  );

  const vista = tomar(
    disponibilidad.vista,
    disponibilidad.vista_db
  );

  const vistaPreferida = tomar(
    disponibilidad.vista_preferida,
    datosMemoriaReserva.vista_preferida,
    datosConsultaReserva.vista_preferida,
    datosExtraidosReserva.vista_preferida
  );

  const capacidadTotal = entero(
    tomar(
      disponibilidad.capacidad_total,
      disponibilidad.capacidad
    )
  );

  const numeroPersonas = entero(
    tomar(
      disponibilidad.numero_personas,
      datosMemoriaReserva.numero_personas,
      datosConsultaReserva.numero_personas,
      datosExtraidosReserva.numero_personas,
      datosMemoriaReserva.total_personas,
      datosConsultaReserva.total_personas
    )
  );

  const numeroNoches = entero(
    tomar(
      disponibilidad.numero_noches,
      datosMemoriaReserva.numero_noches,
      datosConsultaReserva.numero_noches,
      datosExtraidosReserva.numero_noches
    )
  );

  const fechaEntrada = tomar(
    disponibilidad.fecha_entrada,
    disponibilidad.fecha_entrada_texto,
    datosMemoriaReserva.fecha_entrada,
    datosMemoriaReserva.fecha_entrada_texto,
    datosConsultaReserva.fecha_entrada,
    datosConsultaReserva.fecha_entrada_texto,
    datosExtraidosReserva.fecha_entrada,
    datosExtraidosReserva.fecha_entrada_texto
  );

  const precioNoche = numero(
    tomar(
      disponibilidad.precio_noche_cop,
      disponibilidad.precio_cop,
      disponibilidad.precio_noche
    )
  );

  const presupuestoMax = numero(
    tomar(
      disponibilidad.presupuesto_max_cop,
      datosMemoriaReserva.presupuesto_max_cop,
      datosConsultaReserva.presupuesto_max_cop,
      datosExtraidosReserva.presupuesto_max_cop
    )
  );

  const diferenciaPresupuesto = precioNoche !== null && presupuestoMax !== null
    ? Math.max(precioNoche - presupuestoMax, 0)
    : null;

  const totalEstimado = precioNoche !== null && numeroNoches !== null
    ? precioNoche * numeroNoches
    : null;

  const diferenciaTotalEstimada = diferenciaPresupuesto !== null && numeroNoches !== null
    ? diferenciaPresupuesto * numeroNoches
    : null;

  const habitacionesDisponibles = entero(
    tomar(
      disponibilidad.habitaciones_disponibles,
      disponibilidad.total_habitaciones_disponibles,
      codigoHabitacion ? 1 : 0
    )
  );

  const partesSolicitud = [];

  const personasTexto = textoPersonas(numeroPersonas);
  const nochesTexto = textoNoches(numeroNoches);

  if (tipoHabitacionSolicitada) {
    partesSolicitud.push(`tipo ${tipoHabitacionSolicitada}`);
  }

  if (personasTexto) {
    partesSolicitud.push(`para ${personasTexto}`);
  }

  if (nochesTexto) {
    partesSolicitud.push(`por ${nochesTexto}`);
  }

  if (fechaEntrada) {
    partesSolicitud.push(`con entrada ${fechaEntrada}`);
  }

  const resumenSolicitud = partesSolicitud.length > 0
    ? partesSolicitud.join(", ")
    : "según los datos solicitados";

  let respuestaFinal = "";

  if (codigoHabitacion) {
    respuestaFinal =
      `Encontré una habitación disponible para tu solicitud (${resumenSolicitud}), pero no registré la reserva porque supera tu presupuesto máximo. ` +
      `La habitación encontrada es ${codigoHabitacion}, tipo ${tipoHabitacion || "no especificado"}, con ${vista || "vista no especificada"}. ` +
      `El precio por noche es ${dineroCOP(precioNoche)}, mientras que tu presupuesto máximo es ${dineroCOP(presupuestoMax)}.`;
  } else {
    respuestaFinal =
      `No registré la reserva porque la opción encontrada supera tu presupuesto máximo. ` +
      `El precio por noche es ${dineroCOP(precioNoche)}, mientras que tu presupuesto máximo es ${dineroCOP(presupuestoMax)}.`;
  }

  if (diferenciaPresupuesto !== null && diferenciaPresupuesto > 0) {
    respuestaFinal += ` La diferencia es de ${dineroCOP(diferenciaPresupuesto)} por noche.`;
  }

  if (totalEstimado !== null && numeroNoches !== null) {
    respuestaFinal += ` Para ${textoNoches(numeroNoches)}, el total estimado sería de ${dineroCOP(totalEstimado)}.`;
  }

  if (diferenciaTotalEstimada !== null && diferenciaTotalEstimada > 0 && numeroNoches !== null) {
    respuestaFinal += ` La diferencia total estimada frente a tu presupuesto sería de ${dineroCOP(diferenciaTotalEstimada)}.`;
  }

  respuestaFinal += ` Puedes intentar con una habitación más económica, cambiar tus preferencias o aumentar el presupuesto.`;

  return {
    json: {
      tipo_solicitud: "reserva_simulada",

      pregunta_usuario: preguntaUsuario,
      pregunta_normalizada: preguntaNormalizada,
      session_id: sessionId,
      sessionId: sessionId,
      nombre_hotel: nombreHotel,

      codigo_habitacion: codigoHabitacion,
      codigo_habitacion_solicitado: codigoHabitacionSolicitado,

      tipo_habitacion: tipoHabitacion,
      tipo_habitacion_db: tipoHabitacion,
      tipo_habitacion_solicitada: tipoHabitacionSolicitada,

      capacidad_total: capacidadTotal,
      vista: vista,
      vista_preferida: vistaPreferida,

      numero_personas: numeroPersonas,
      numero_noches: numeroNoches,
      fecha_entrada: fechaEntrada,

      precio_noche_cop: precioNoche,
      presupuesto_max_cop: presupuestoMax,
      diferencia_presupuesto_cop: diferenciaPresupuesto,
      diferencia_total_estimada_cop: diferenciaTotalEstimada,
      total_estimado_cop: totalEstimado,

      habitaciones_disponibles: habitacionesDisponibles,

      coincide_vista_preferida: tomar(
        disponibilidad.coincide_vista_preferida,
        null
      ),

      cumple_presupuesto: false,

      resultado_disponibilidad: tomar(
        disponibilidad.resultado_disponibilidad,
        "disponible_fuera_de_presupuesto"
      ),

      motivo_no_disponibilidad: tomar(
        disponibilidad.motivo_no_disponibilidad,
        "La habitación está disponible, pero supera el presupuesto máximo del usuario."
      ),

      motivo_no_registro:
        "No se registró la reserva porque la habitación disponible supera el presupuesto máximo indicado por el usuario.",

      respuesta_final: respuestaFinal,

      estado: "reserva_pendiente_por_presupuesto",
      estado_reserva: "no_registrada_por_presupuesto",

      recomendacion:
        "Intentar con una habitación más económica, ajustar preferencias o aumentar el presupuesto.",

      fuente: "Code - Fuera de Presupuesto",
      timestamp: new Date().toISOString()
    }
  };
});
